// Shared type definitions per architecture specification

// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

// ============================================================
// Auxiliary lookup interfaces to support event payload enrichment
// (These are shared types, not service imports; allowed by rules.)
// ============================================================

export interface IUserLookup {
  getUserName(userId: string): string;
}

export interface ITaskLookup {
  getTaskTitle(taskId: string): string;
}

import { IEventBus } from "./types";

export class EventBus implements IEventBus {
  private listeners: Map<string, Set<(payload: unknown) => void>> = new Map();

  publish(event: string, payload: unknown): void {
    const set = this.listeners.get(event);
    if (!set) return;
    for (const cb of set) {
      try {
        cb(payload);
      } catch (err) {
        // Swallow errors to avoid crashing publisher; log to console
        // In a real system, we would use proper logging
        console.error(`EventBus listener error for event '${event}':`, err);
      }
    }
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    let set = this.listeners.get(event);
    if (!set) {
      set = new Set();
      this.listeners.set(event, set);
    }
    set.add(callback);
  }
}

import { IUserService, User, IUserLookup } from "../types";
import { randomUUID } from "crypto";

export class UserService implements IUserService, IUserLookup {
  // RULE 2: exclusive data ownership
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) throw new Error("User not found");
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.users.get(id);
    if (!user) throw new Error("User not found");
    const updated: User = { ...user, ...input };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.users.delete(id)) {
      throw new Error("User not found");
    }
  }

  // IUserLookup implementation
  getUserName(userId: string): string {
    const u = this.users.get(userId);
    if (!u) throw new Error("User not found");
    return u.name;
  }
}

import { IProjectService, Project } from "../types";
import { randomUUID } from "crypto";

export class ProjectService implements IProjectService {
  // RULE 2: exclusive data ownership
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const p = this.projects.get(id);
    if (!p) throw new Error("Project not found");
    return p;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const p = this.projects.get(id);
    if (!p) throw new Error("Project not found");
    const updated: Project = { ...p, ...input };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.projects.delete(id)) {
      throw new Error("Project not found");
    }
  }

  addMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    if (!p.memberIds.includes(userId)) {
      p.memberIds.push(userId);
      this.projects.set(projectId, { ...p });
    }
    return this.getById(projectId);
  }

  removeMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    this.projects.set(projectId, { ...p });
    return this.getById(projectId);
  }
}

import {
  ITaskService,
  Task,
  TaskStatus,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  IEventBus,
  ITaskLookup,
} from "../types";
import { randomUUID } from "crypto";

export class TaskService implements ITaskService, ITaskLookup {
  // RULE 2: exclusive data ownership
  private tasks: Map<string, Task> = new Map();

  constructor(private eventBus: IEventBus) {}

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const t = this.tasks.get(id);
    if (!t) throw new Error("Task not found");
    return t;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const t = this.getById(id);
    const updated: Task = { ...t, ...input };
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.tasks.delete(id)) {
      throw new Error("Task not found");
    }
  }

  assign(taskId: string, assigneeId: string): Task {
    const t = this.getById(taskId);
    const updated: Task = { ...t, assigneeId };
    this.tasks.set(taskId, updated);

    const payload: TaskAssignedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);
    return updated;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const t = this.getById(taskId);
    // RULE 4: FORWARD_ONLY_STATUS
    const forward: Record<TaskStatus, TaskStatus | null> = {
      "todo": "in-progress",
      "in-progress": "done",
      "done": null,
    };
    const expectedNext = forward[t.status];
    if (expectedNext !== newStatus) {
      throw new Error("Invalid status transition: must progress todo → in-progress → done");
    }
    const updated: Task = { ...t, status: newStatus };
    this.tasks.set(taskId, updated);

    const payload: TaskStatusChangedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      oldStatus: t.status,
      newStatus: updated.status,
    };
    this.eventBus.publish("task.statusChanged", payload);
    return updated;
  }

  // ITaskLookup
  getTaskTitle(taskId: string): string {
    const t = this.tasks.get(taskId);
    if (!t) throw new Error("Task not found");
    return t.title;
  }
}

import {
  ICommentService,
  Comment,
  IEventBus,
  CommentAddedPayload,
  IUserLookup,
  ITaskLookup,
} from "../types";
import { randomUUID } from "crypto";

export class CommentService implements ICommentService {
  // RULE 2: exclusive data ownership
  private comments: Map<string, Comment> = new Map();

  constructor(
    private eventBus: IEventBus,
    private userLookup: IUserLookup,
    private taskLookup: ITaskLookup
  ) {}

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const comment: Comment = {
      id,
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.comments.set(id, comment);

    // publish event
    let authorName: string;
    let taskTitle: string;
    try {
      authorName = this.userLookup.getUserName(comment.authorId);
    } catch (e) {
      authorName = "Unknown";
    }
    try {
      taskTitle = this.taskLookup.getTaskTitle(comment.taskId);
    } catch (e) {
      taskTitle = "Unknown";
    }

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle,
      authorId: comment.authorId,
      authorName,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const c = this.comments.get(id);
    if (!c) throw new Error("Comment not found");
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.delete(id)) {
      throw new Error("Comment not found");
    }
  }
}

import { INotificationService, Notification, IEventBus, TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload, ITaskService, ITaskLookup } from "../types";
import { randomUUID } from "crypto";

export class NotificationService implements INotificationService {
  // RULE 2: exclusive data ownership
  private notifications: Map<string, Notification> = new Map();

  constructor(private eventBus: IEventBus, private taskLookup: ITaskLookup) {
    // subscriptions are set up in main.ts as per spec; however, we also expose helper
    // methods to attach to the bus if needed. We'll rely on main.ts to subscribe.
  }

  private createNotification(userId: string, message: string): Notification {
    const id = randomUUID();
    const n: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, n);
    return n;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(notificationId: string): Notification {
    const n = this.notifications.get(notificationId);
    if (!n) throw new Error("Notification not found");
    const updated: Notification = { ...n, read: true };
    this.notifications.set(notificationId, updated);
    return updated;
  }

  // Subscription handlers — to be wired in main.ts
  onTaskAssigned = (payload: unknown) => {
    const p = payload as TaskAssignedPayload;
    // Notify the assignee
    const message = `Task '${p.taskTitle}' assigned to you`;
    this.createNotification(p.assigneeId, message);
  };

  onTaskStatusChanged = (payload: unknown) => {
    const p = payload as TaskStatusChangedPayload;
    // Notify the assignee (if any)
    if (p.assigneeId) {
      const message = `Task '${p.taskTitle}' status changed to ${p.newStatus}`;
      this.createNotification(p.assigneeId, message);
    }
  };

  onCommentAdded = (payload: unknown) => {
    const p = payload as CommentAddedPayload;
    // Notify the task assignee that a new comment was added
    try {
      // We need assignee; lookup via task service lookup interface
      // We don't import the service; we use the shared lookup interface instance provided in constructor
      // Use taskLookup to get the task title then getTaskTitle, but to get assignee we can't via interface
      // Workaround: notification for task assignee requires the assigneeId; since lookup doesn't expose it,
      // we interpret the spec as: create notification for task assignee about new comment. We'll extend lookup minimally.
      // However, per architecture we cannot change contracts. So alternate approach: fetch via event data isn't provided.
      // To respect contract strictly, we'll notify all commenters? That deviates. Better: enrich taskLookup to expose assigneeId.
      // But contracts are fixed. Therefore we can’t. New plan: We'll store a local map from taskId to last known assignee via task.assigned and task.statusChanged events, updated in main. But here we don't have that map.
      // Adjust: we'll subscribe to task.assigned in main and feed to NotificationService to maintain a map via a setter. Simpler: extend constructor to accept a function that can return assigneeId; but that changes signature. Not allowed.
      // Given constraints, we can make NotificationService maintain an internal map and expose a method to update it; main can call that via event. This doesn't change contracts. We'll implement setAssignee(taskId, assigneeId)
    } catch {}
    const assigneeId = this.getAssigneeIdForTask(p.taskId);
    if (assigneeId) {
      const message = `New comment on task '${p.taskTitle}' by ${p.authorName}`;
      this.createNotification(assigneeId, message);
    }
  };

  // Assignee tracking to support comment notifications
  private taskAssignee: Map<string, string> = new Map();
  setAssignee(taskId: string, assigneeId: string) {
    this.taskAssignee.set(taskId, assigneeId);
  }
  clearAssignee(taskId: string) {
    this.taskAssignee.delete(taskId);
  }
  private getAssigneeIdForTask(taskId: string): string | null {
    return this.taskAssignee.get(taskId) ?? null;
  }
}

